style.css:
/* Hacker Instagram Theme */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("instagram.com") {
/* Background color */
  body {
    background-color: #0d0d0d !important;
  }

  /* Text color */
  .-cx-PRIVATE-Post__root, .-cx-PRIVATE-Post__header, .-cx-PRIVATE-Post__footer {
    color: #00ff00 !important;
  }

  /* Navigation bar */
  .-cx-PRIVATE-NavBar__root {
    background-color: #1a1a1a !important;
  }

  /* Links */
  a {
    color: #00ff00 !important;
  }

  /* Buttons */
  button {
    background-color: #1a1a1a !important;
    color: #00ff00 !important;
  }

  /* Input fields */
  input, textarea {
    background-color: #1a1a1a !important;
    color: #00ff00 !important;
  }
}
